namespace sv_2c831abd40b44f86ac0dfc155fa65adf.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// Interactive components subscribe to OnThemeChanged to re-render when any
/// component mutates theme or accent color.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Subscribers should call StateHasChanged (on the UI sync context).
    /// </summary>
    public event Action? OnThemeChanged;

    private void NotifyChanged() => OnThemeChanged?.Invoke();

    public void Dispose() => OnThemeChanged = null;
}

@* Interactive island embedded in the static MainLayout header *@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<span class="badge" style="background-color: @ThemeSvc.AccentColor;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnThemeChanged += OnChanged;
    }

    private void OnChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnThemeChanged -= OnChanged;
}

@* Interactive island for quick theme cycling — can be placed in sidebar, header, etc. *@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Current: @ThemeSvc.Theme — click to cycle">
    @GetIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnThemeChanged += OnChanged;
    }

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️ Light",
        ThemeMode.Dark   => "🌙 Dark",
        _                => "💻 System"
    };

    private void OnChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnThemeChanged -= OnChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var active = ThemeSvc.Theme == mode;
                <button class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-2 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnAccentChanged" />
            <span class="text-muted">@ThemeSvc.AccentColor</span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeSvc.Theme</strong><br />
            Accent:
            <span class="badge" style="background-color: @ThemeSvc.AccentColor;">
                @ThemeSvc.AccentColor
            </span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnThemeChanged += OnChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void OnChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnThemeChanged -= OnChanged;
}

